<template>
  <div class="audience-site">
    <a class="skip" href="#audience-main">Skip to content</a>
    <header>
      <router-link class="brand" to="/p/tisi"><img :src="config.logoUrl" alt="" /><span>{{ config.siteName }}<small>{{ config.tagline }}</small></span></router-link>
      <button class="menu" type="button" :aria-expanded="menuOpen" aria-controls="audience-nav" @click="menuOpen = !menuOpen">Menu <span aria-hidden="true">☰</span></button>
      <nav id="audience-nav" :class="{ open: menuOpen }" aria-label="Primary" @keydown.esc="menuOpen = false">
        <router-link v-for="item in navigation" :key="item.slug" :to="`/p/tisi${item.slug ? '/' + item.slug : ''}`" :aria-current="item.slug === slug ? 'page' : undefined" @click="menuOpen = false">{{ item.label }}</router-link>
      </nav>
      <a class="button header-cta" :href="cta">{{ config.ctaButtonLabel }} <span aria-hidden="true">→</span></a>
    </header>
    <main id="audience-main" tabindex="-1">
      <section class="hero" :style="photo(page.heroImageUrl, true)">
        <div class="wrap hero-content"><p class="eyebrow">{{ page.eyebrow }}</p><h1>{{ page.title }}</h1><p class="intro">{{ page.subtitle }}</p><div class="actions"><a class="button" :href="cta">Get Started <span aria-hidden="true">→</span></a><a class="button outline" href="#support">Explore Services</a></div></div>
      </section>
      <section class="pillars" aria-label="Our focus"><div class="wrap pillar-grid"><div v-for="(text, i) in page.pillars" :key="text"><span class="icon" aria-hidden="true" v-html="tisiIconSvg(['peak', 'brain', 'heart', 'chart'][i])" /><span>{{ text }}</span></div></div></section>
      <section id="support" class="wrap support">
        <div><p class="eyebrow">Comprehensive, personalized care</p><h2>{{ page.sectionTitle }}</h2><p>{{ page.sectionBody }}</p><a class="text-link" :href="servicesSlug === slug ? '#service-0' : `/p/tisi/${servicesSlug}`">{{ servicesSlug === slug ? 'Explore support below' : 'Explore ' + page.audience.toLowerCase() + ' services' }} <span aria-hidden="true">→</span></a></div>
        <img class="portrait" :style="{ objectPosition: page.audience === 'Athletes' ? '25% center' : '65% center' }" :src="page.portraitImageUrl" :alt="`${page.audience} in a mountain landscape`" width="887" height="887" loading="lazy" />
        <div class="support-list"><p class="eyebrow">Common areas we support</p><a v-for="(item, i) in page.cards" :key="item.title" :href="`#service-${i}`"><span class="small-icon" aria-hidden="true" v-html="tisiIconSvg(item.iconKey)" />{{ item.title }}</a></div>
      </section>
      <section class="wrap service-grid" aria-label="Services"><article v-for="(item, i) in page.cards" :id="`service-${i}`" :key="item.title" tabindex="-1"><span class="icon" aria-hidden="true" v-html="tisiIconSvg(item.iconKey)" /><h3>{{ item.title }}</h3><p>{{ item.body }}</p><a :href="cta" :aria-label="`Ask about ${item.title}`">Ask about this support <span aria-hidden="true">→</span></a></article></section>
      <section v-if="page.audience === 'Athletes'" class="wrap sports"><p class="eyebrow">Support for every athlete</p><h2>All athletes. All journeys.</h2><div><img v-for="sport in tisiSports" :key="sport.label" :src="sport.image" :alt="sport.label" width="240" height="240" loading="lazy" /></div></section>
      <section class="banner" :style="photo(page.bannerImageUrl)"><div class="wrap"><p class="eyebrow">A stronger tomorrow</p><h2>{{ page.bannerTitle }}</h2><p>Take the next step toward support that fits your needs.</p><a class="button" :href="cta">Get Started <span aria-hidden="true">→</span></a></div></section>
      <section class="wrap process"><div><p class="eyebrow">How it works</p><h2>Simple steps.<br />Real progress.</h2></div><ol><li v-for="(step, i) in steps" :key="step.title"><span class="number">{{ i + 1 }}</span><div><h3>{{ step.title }}</h3><p>{{ step.body }}</p></div></li></ol></section>
      <section v-if="bodyHtml" class="wrap agency-copy"><h2>{{ contentPage.title || 'More about our care' }}</h2><div v-html="bodyHtml" /></section>
      <section class="wrap faq"><div><p class="eyebrow">Frequently asked questions</p><h2>Your questions.<br />Answered.</h2></div><div class="questions"><details v-for="[question, answer] in page.faq" :key="question"><summary>{{ question }}</summary><p>{{ answer }}</p></details></div></section>
