<script setup>
import { computed, ref, watch } from 'vue';
import DOMPurify from 'dompurify';
import { marked } from 'marked';
import { tisiAudiencePages, tisiSports } from '../../constants/tisiAudiencePages';
import { tisiIconSvg } from '../../constants/tisiMarketingLanding';
import { isPlaceholderCopy, landingDestination, safeMarketingHref } from '../../utils/marketingPageQuality';
const props = defineProps({ slug: { type: String, required: true }, config: { type: Object, required: true }, contentPage: { type: Object, default: () => ({}) }, contentPages: { type: Array, default: () => [] } });
const menuOpen = ref(false);
watch(() => props.slug, () => { menuOpen.value = false; });
const page = computed(() => {
  const defaults = tisiAudiencePages[props.slug];
  const result = { ...defaults };
  for (const field of ['heroImageUrl', 'portraitImageUrl', 'bannerImageUrl', 'heroPosition', 'heroMobilePosition']) {
    const value = props.contentPage[field];
    if (value && (field.includes('Position') || /^(\/[^/]|https?:\/\/)/.test(safeMarketingHref(value)))) result[field] = value;
  }
  if (props.contentPage.heroTitle && !isPlaceholderCopy(props.contentPage.heroTitle)) result.title = props.contentPage.heroTitle;
  if (props.contentPage.heroSubtitle && !isPlaceholderCopy(props.contentPage.heroSubtitle)) result.subtitle = props.contentPage.heroSubtitle;
  return result;
});
const cta = computed(() => safeMarketingHref(props.config.ctaHref) || '/join/tisi');
const legalLinks = computed(() => (props.config.legalFooterLinks || []).map(link => ({ ...link, href: landingDestination(link.href, { slug: 'tisi', contentPages: props.contentPages }) })).filter(link => link.href));
const servicesSlug = computed(() => ({ Men: 'mens-services', Boys: 'boys-services', Athletes: 'athlete-services' })[page.value.audience]);
const bodyHtml = computed(() => {
  const text = props.contentPage.body || '';
  return isPlaceholderCopy(text) ? '' : DOMPurify.sanitize(marked.parse(text, { async: false }));
});
const photo = (url, hero = false) => ({ backgroundImage: `${hero ? 'linear-gradient(90deg, rgba(0,22,36,.93), rgba(0,22,36,.52) 42%, rgba(0,22,36,.04) 75%)' : 'linear-gradient(90deg, #001624 0%, rgba(0,22,36,.98) 36%, rgba(0,22,36,.4) 60%, rgba(0,22,36,.04) 80%)'}, url(${JSON.stringify(url)})`, '--photo-position': page.value.heroPosition || 'center', '--photo-mobile-position': page.value.heroMobilePosition || '75% center', backgroundSize: !hero ? 'cover' : undefined });
const navigation = [{ label: 'Home', slug: '' }, { label: 'For Men', slug: 'men' }, { label: 'For Boys', slug: 'boys' }, { label: 'For Athletes', slug: 'athletes' }];
const steps = [{ title: 'Connect', body: 'Share your needs and questions through the online intake.' }, { title: 'Get matched', body: 'Discuss the right support for your goals and needs.' }, { title: 'Build skills', body: 'Work with your provider on practical tools for everyday life.' }, { title: 'Grow stronger', body: 'Review your progress and next steps together.' }];
</script>
